import React, { Component } from "react";
import { FormattedMessage } from "react-intl";
import "react-datepicker/dist/react-datepicker.css";
import "react-dates/initialize";
import "react-loader-spinner/dist/loader/css/react-spinner-loader.css";
import Loader from "react-loader-spinner";
import Pagination2 from "react-js-pagination";
import "react-dates/lib/css/_datepicker.css";

// Redux
import { connect } from "react-redux";
import { bindActionCreators } from "redux";
import { fetchPostilionSummaryItem, fetchPostilionSummarySearch } from "../../../actions/filesets";
import { openModal, closeModal } from "../../../actions/utils";

// components
import {
	Card,
	CardBody,
	CardHeader,
	Col,
	Row,
	Table,
	Input,
	Dropdown,
	DropdownToggle,
	DropdownMenu,
	DropdownItem,
	Button,
} from "reactstrap";
import PostingTable from "../../../components/PostingTable";
import PostingTableHeader from "../../../components/PostingTableHeader";
import PostilionLogSearchModal from "../../../components/PostilionLogSearchModal";

// utility functions
// import { setTableHeader } from "../../../Utils/utilityFunctions";

class PostilionDetails extends Component {
	constructor (props) {
		super(props);
		this.state = {
			activePage   : 1,
			toggle       : false,
			searchBy     : "Search By",
			searchValue  : "",
			isError      : "secondary",
			isValueError : false,
			selectedCode : "",
		};
		this.handlePageChange = this.handlePageChange.bind(this);
	}

	static getDerivedStateFromProps (props, state) {
		if (props.match.params.page !== state.activePage) {
			return {
				activePage : parseInt(props.match.params.page),
			};
		}

		// Return null if the state hasn't changed
		return null;
	}

	componentDidMount () {
		this.props.fetchPostilionSummaryItem(this.props.match.params.date, this.props.match.params.page - 1);
	}

	componentDidUpdate (prevProps) {
		if (this.props.match.params.page !== prevProps.match.params.page) {
			this.props.fetchPostilionSummaryItem(this.props.match.params.date, this.props.match.params.page - 1);
		}

		if (prevProps.match.params.date !== this.props.match.params.date) {
			this.props.fetchPostilionSummaryItem(this.props.match.params.date, this.props.match.params.page - 1);
		}

		if (this.props.selectedAffiliateCode !== prevProps.selectedAffiliateCode) {
			this.props.fetchPostilionSummaryItem(this.props.match.params.date, this.props.match.params.page - 1);
		}
	}

	handlePageChange = (pageNumber) => {
		this.props.history.push(`/downstream/logs/postilion/${this.props.match.params.date}/${pageNumber}`);
		this.setState({ activePage: pageNumber });
	};

	toggle = () => this.setState({ toggle: !this.state.toggle, isError: "secondary" }); // handle drop down toggle

	handleSelect = (event) => {
		// control search input
		this.setState({
			searchValue  : event.target.value.trim(), // remove all white space useful when user copies and pastes values into search form
			isValueError : false,
		});
	};

	handleSelectSearchBy = (searchItem) => {
		if (searchItem === "pan") {
			this.props.openModal(); // open advance postilion search
			this.setState({ isValueError: false });
		} else {
			this.setState({ searchBy: searchItem, isValueError: false });
		}
	};

	handleSubmitSearch = () => {
		if (this.state.searchBy !== "pan") {
			if (!this.state.searchValue) {
				this.setState({ isValueError: true });
				return;
			}

			if (this.state.searchBy === "Search By") {
				this.setState({ isError: "danger" });
				return;
			}

			this.props.history.push(
				`/downstream/logs/postilion/${this.props.match.params.date}/${this.state.searchBy}/${this.state
					.searchValue}/1`,
			);
		}

		this.setState({
			searchValue  : "",
			searchBy     : "Search By",
			isError      : "secondary",
			isValueError : false,
		});

		return;
	};

	render () {
		const searchByValues = [
			{ formName: "Auth Id", apiName: "authId" },
			{ formName: "Pan", apiName: "pan" },
			{ formName: "From Account Id", apiName: "fromAccountId" },
		];
		const PostilionLogSummaryItemHeader = [
			"File Date",
			"Tran Nr",
			"Message Type",
			"Tran Type",
			"Source Node Name",
			"Sink Node Name",
			"Pan",
			"From Account Id",
			"Terminal Id",
			"Card Acceptor Id Code",
			"Card Acceptor Name Loc",
			"Rsp Code Rsp",
			"Date Time",
			"Date",
			"Time",
			"Date Time Tran Gmt",
			"System Trace Audit Nr",
			"Tran Amount Rsp",
			"Tran Cash Rsp",
			"Tran Currency Code",
			"Settle Currency Code",
			"Settle Amount Req",
			"Settle Amount Rsp",
			"Settle Cash Rsp",
			"Settle Amount Impact",
			"Switch Key",
			"Type",
			"Retrieval Reference Nr",
			"Auth Id Rsp",
		];

		return (
			<div className='animated fadeIn'>
				<Row>
					<Col>
						<Card>
							<CardHeader>
								<section className='d-flex justify-content-between align-items-center'>
									<article>
										<i className='fa fa-table mx-2' aria-hidden='true' />
										<FormattedMessage
											id='Postilion Summary Table'
											defaultMessage='Postilion Summary Table'
										/>
									</article>
									<article className='d-flex justify-content-between'>
										<Dropdown isOpen={this.state.toggle} toggle={this.toggle}>
											<DropdownToggle caret color={this.state.isError}>
												{this.state.searchBy}
											</DropdownToggle>
											<DropdownMenu>
												{" "}
												{/* FormattedMessage component is used to translate the value to multi languages as already configured Always use */}
												{searchByValues.map((searchItem, index) => (
													<DropdownItem
														key={index}
														onClick={() => this.handleSelectSearchBy(searchItem.apiName)}
													>
														{searchItem.formName}
													</DropdownItem>
												))}
											</DropdownMenu>
										</Dropdown>
										<div className='d-flex justify-content-between'>
											<PostilionLogSearchModal
												openPanSearch={this.props.isModalOpen ? this.props.isModalOpen : false}
												closePanSearch={() => this.props.closeModal()}
												// handlePanSearch={this.handlePanSearch}
												searchDate={this.props.match.params.date}
											/>
											<Input
												className='mx-1'
												onChange={this.handleSelect}
												value={this.state.searchValue}
												invalid={this.state.isValueError}
											/>
											<Button
												// type='button'
												onClick={() =>
													this.handleSubmitSearch(
														// pass the whole postilion data when available.
														this.props.postilionLogSummaryItem.content
															? this.props.postilionLogSummaryItem.content
															: [],
													)}
												type='button'
												className={"btn btn-small btn-success"}
											>
												<FormattedMessage id='Submit' defaultMessage='Submit' />
											</Button>
										</div>
									</article>
								</section>
							</CardHeader>
							<CardBody>
								{/* Handle Loading */}
								{!this.props.postilionLogSummaryItem &&
								!this.props.postilionLogSummaryItemError && (
									<article className='d-flex justify-content-center align-items-center'>
										<div>
											<Loader type='ThreeDots' color='#00BFFF' height={100} width={100} />
										</div>
									</article>
								)}

								{/* Handle Error 404 */}
								{!this.props.postilionLogSummaryItem &&
								this.props.postilionLogSummaryItemError &&
								this.props.postilionLogSummaryItemError.response.data && (
									<div className={"d-flex justify-content-center align-items-center text-danger"}>
										<p>
											<FormattedMessage
												id={this.props.postilionLogSummaryItemError.response.data.message}
												defaultMessage={
													this.props.postilionLogSummaryItemError.response.data.message
												}
											/>
										</p>
									</div>
								)}

								{/* Handle All Error 400 */}
								{!this.props.postilionLogSummaryItem &&
								this.props.postilionLogSummaryItemError &&
								this.props.postilionLogSummaryItemError.response.data === "" && (
									<div className={"d-flex justify-content-center align-items-center text-danger"}>
										<p>
											<FormattedMessage
												id={"Error unable to load entries!"}
												defaultMessage={"Error unable to load entries!"}
											/>
										</p>
									</div>
								)}

								{/* show table only if there is no error. */}
								{!this.props.postilionLogSummaryItemError &&
								this.props.postilionLogSummaryItem &&
								this.props.postilionLogSummaryItem.content.length > 0 && (
									<Table
										hover
										bordered
										striped
										responsive
										size='sm'
										className='table-outline mb-0 d-sm-table'
										style={{ minWidth: "470%", textTransform: "capitalize" }}
									>
										<thead className='thead-light'>
											<PostingTableHeader
												headerType={"array"}
												headerPayload={PostilionLogSummaryItemHeader}
											/>
											{/* <PostingTableHeader
												headerPayload={
													this.props.postilionLogSummaryItem ? (
														setTableHeader(this.props.postilionLogSummaryItem.content)
													) : (
														[]
													)
												}
												headerType={"array"}
											/> */}
										</thead>
										<tbody>
											<PostingTable
												tableName='postilionLogSummary'
												dataRecords={
													this.props.postilionLogSummaryItem ? (
														this.props.postilionLogSummaryItem.content
													) : (
														[]
													)
												}
											/>
										</tbody>
									</Table>
								)}

								{this.props.postilionLogSummaryItem ? (
									<nav>
										<Pagination2
											activePage={this.state.activePage}
											itemsCountPerPage={this.props.postilionLogSummaryItem.size}
											totalItemsCount={
												(this.props.postilionLogSummaryItem &&
													this.props.postilionLogSummaryItem.totalElements) ||
												null
											}
											pageRangeDisplayed={20}
											onChange={this.handlePageChange}
										/>
									</nav>
								) : (
									""
								)}
							</CardBody>
						</Card>
					</Col>
				</Row>
			</div>
		);
	}
}

const mapStateToProps = (state) => {
	return {
		postilionLogSummaryItem      : state.fileSets.postilionLogSummaryItem,
		postilionLogSummaryItemError : state.fileSets.postilionLogSummaryItemError,
		selectedAffiliateCode        : state.fileSets.selectedAffiliateCode,
		isModalOpen                  : state.utils.openModal,
	};
};

const mapDispatchToProps = (dispatch) => {
	return bindActionCreators(
		{
			fetchPostilionSummaryItem,
			fetchPostilionSummarySearch,
			openModal,
			closeModal,
		},
		dispatch,
	);
};

export default connect(mapStateToProps, mapDispatchToProps)(PostilionDetails);
