import React, { useState } from "react";
import { useHistory } from "react-router-dom";
import { Button, Modal, ModalHeader, ModalBody, ModalFooter, Label, Input } from "reactstrap";

const PostilionLogSearchModal = ({ className, openPanSearch, closePanSearch, searchDate }) => {
	const history = useHistory();
	const [ firstSixPan, setFirstSixPan ] = useState("");
	const [ firstSixPanToDisplay, setFirstSixPanToDisplay ] = useState("");
	const [ lastFourPan, setLastFourPan ] = useState("");
	const [ lastFourPanToDisplay, setLastFourToDisplay ] = useState("");
	const [ isFirstSixPanError, setFirstSixPanError ] = useState(false);
	const [ isLastFourPanError, setLastFourPanError ] = useState(false);

	const lastFourDigits = /^\d{4}$/; // regex to test for last for digit
	const firstSixDigits = /^\d{6}$/; // regx to test for first six digits. 

	const handleFirstSixPanInputChange = (event) => {
		if(event.target.value.length > 6) {
			return
		}
		let postData = firstSixPan;
		if(/\d+/g.test(event.target.value[event.target.value.length - 1])){ // Check if the last index of onChage is a number
			 postData += event.target.value[event.target.value.length - 1];
		} else {
			postData = postData.slice(0, -1);
		}
		setFirstSixPan(postData); 
		setFirstSixPanToDisplay(event.target.value.replace(/\d+/g,"X")); // Mask the User Input
		let validate = firstSixDigits.test(postData); // Validating Using the postData Not event.target.value again
		validate ? setFirstSixPanError(false) : setFirstSixPanError(true);
	};

	const handleLastFourPanInputChange = (event) => {
		if(event.target.value.length > 4) {
			return
		}
		let postData = lastFourPan;
		if(/\d+/g.test(event.target.value[event.target.value.length - 1])){ // Check if the last index of onChage is a number
			 postData += event.target.value[event.target.value.length - 1];
		} else {
			postData = postData.slice(0, -1);
		}
		setLastFourPan(postData);
		setLastFourToDisplay(event.target.value.replace(/\d+/g,"X")); // Mask the User Input
		let validate = lastFourDigits.test(postData); // Validating Using the postData Not event.target.value again
		validate ? setLastFourPanError(false) : setLastFourPanError(true);
	};

	const handlePanSearch = (firstSixPanNumber, lastFourPanNumber) => {
		if (firstSixPan === "") {
			// handle no search values
			setFirstSixPanError(true);
			return;
		}

		if (lastFourPan === "") {
			setLastFourPanError(true);
			return;
		}

		if (isFirstSixPanError || isLastFourPanError) {
			// handle invalid search values
			return;
		}

		const panNumber = `${firstSixPanNumber.trim()}******${lastFourPanNumber.trim()}`; // construct the pan
		closePanSearch(); // close modal
		history.push(`/downstream/logs/postilion/${searchDate}/pan/${panNumber}`); // redirect to search result
	};

	const handleCancelPanSearch = () => {
		setFirstSixPanError(false);
		setLastFourPanError(false);
		setFirstSixPan("");
		setLastFourPan("");
		setFirstSixPanToDisplay("");
		setLastFourToDisplay("");
		closePanSearch();
	};

	return (
		<Modal isOpen={openPanSearch} className={className}>
			<ModalHeader className='d-flex justify-content-center align-items-center'>
				<p style={{ fontSize: "1rem" }}>
					<strong>Enter Pan Search Details</strong>
				</p>
			</ModalHeader>
			<ModalBody>
				<article className='d-flex flex-column justify-content-between'>
					<div className='my-2'>
						<Label for='firtSixDigit'>Enter first six pan digits</Label>
						<Input
							type='text'
							name='firtSixDigit'
							id='firtSixDigit'
							onChange={handleFirstSixPanInputChange}
							value={firstSixPanToDisplay}
							invalid={isFirstSixPanError}
						/>
					</div>

					<div className='my-2'>
						<Label for='lastFourDigits'>Enter Last four pan digits</Label>
						<Input
							type='text'
							name='lastFourDigits'
							id='lastFourDigits'
							onChange={handleLastFourPanInputChange}
							value={lastFourPanToDisplay}
							invalid={isLastFourPanError}
						/>
					</div>
				</article>
			</ModalBody>
			<ModalFooter>
				<Button color='success' onClick={() => handlePanSearch(firstSixPan, lastFourPan)}>
					Submit
				</Button>{" "}
				<Button color='danger' onClick={() => handleCancelPanSearch()}>
					Cancel
				</Button>
			</ModalFooter>
		</Modal>
	);
};

export default PostilionLogSearchModal;
